mod = 10 ** 9 + 7
p, k = map(int, input().split())
if k == 0:
    print(pow(p, p - 1, mod))
elif k == 1:
    print(pow(p, p, mod))
else:
    z = [1]
    while True:
        z.append((z[-1] * k) % p)
        if z[-1] == z[0]:
            break
    print(pow(p, (p - 1) // len(z), mod))

